"""One global location/context contract for Winuvo Adaptive Living."""
def spec(description,required=None,optional=None,timeout=20000):
 return {'description':description,'required':required or {},'optional':optional or {},'timeout_ms':timeout}
def field(typ,description):return {'type':typ,'description':description}
ADAPTIVE_SPECS={
 'adaptive.context':spec('Read the GLOBAL Winuvo context: current ZIP, revision, resolved time zone, local time/date/season/daypart, provenance-tagged weather/air/news, feed freshness and honest device availability. All adaptive panels use this same context. No physical device adapters are connected yet.'),
 'adaptive.configure':spec('Main adaptation entry point: when the user tells Muse a NEW ZIP, call this. It persists the location, invalidates old-location facts/panels, increments the context revision and triggers a whole-home Muse refresh automatically. Resolve the new ZIP time zone from an authoritative geocoder then set the SAME ZIP with time_zone and refresh=false. Actual device settings and media playback are preserved. Purifier policy proposes on/off/hold with hysteresis; it cannot operate disconnected hardware.',optional={'postal_code':field('string','Five-digit US ZIP requested by the user.'),'time_zone':field('string','Resolved IANA time zone; do not assume the old ZIP time zone.'),'refresh':field('boolean','Default true on ZIP change; false when resolving metadata during an active refresh.'),'report':field('boolean','Also request a daily picture PDF.'),'purifier':field('object','enabled boolean, on_above_aqi (default 100), off_below_aqi (default 50); off < on, range 0..500. Demonstration thresholds, not medical guidance.')}),
 'adaptive.publish':spec('Publish a coherent update for the CURRENT global ZIP and revision. Old revisions are rejected. First read adaptive.context. Supply normalized sourced inputs and ten XML panel data objects, then Home remixes them. Weather/news/air facts must be sourced, dated and basis-labelled; climate/lighting/energy are recommendations until devices/meters connect. BOTH lighting and energy depend on local time, date, season, daylight and weather. Security is motion/person/enrolled-face/camera/door evidence, or awaiting feeds. Sound is listener-guided home-theater tuning; never manufacture choices. Preserve media and EQ.',required={'postal_code':field('string','Current ZIP from adaptive.context.'),'revision':field('integer','Current location revision; stale updates are rejected.')},optional={'inputs':field('object','weather, air_quality, news. Each: {data:object,basis:measured|model|feed,source:HTTPS URL,timestamp:ISO8601 with offset}. Weather data temperature_c,condition,humidity_percent,sunrise,sunset; air_quality aqi,pm2_5; news stories [{title,url,published}]. CAMS must be model, not measured.'),'panels':field('object','Map template IDs home/weather/news/air/climate/lighting/energy/security/sound/scenes to declared XML fields. Short hero/summary/metric values; source/date and honest unknown states. Do not show samples as live.')}),
 'adaptive.update':spec('Update sourced global context inputs without requiring a panel publication. Same revision/ZIP contract as adaptive.publish.',required={'postal_code':field('string','Current ZIP.'),'revision':field('integer','Current revision.'),'inputs':field('object','Provenance-tagged weather, air_quality, news input objects.')}),
 'adaptive.evaluate':spec('Evaluate the shared context into recommendation-only climate, seasonal/time-aware lighting and energy, purifier on/off/hold, and honest security availability. No connected actuators; executed=false. Outdoors is not an indoor sensor.'),
 'adaptive.refresh':spec('Request a whole-home Muse refresh for the existing ZIP; automatic on ZIP change. Use for a user refresh or daily briefing. During a refresh do NOT recursively call this; fetch facts and call adaptive.publish instead.',optional={'report':field('boolean','Generate a daily picture PDF after publishing fresh context.')}),
 'adaptive.report':spec('Generate the current daily PDF ON THE BOARD with ten real Qt/LVGL panel pictures across five pages, local ZIP/date and labelled sources. Does not stop media or retune sound. Returns report basename, size and metadata. Read chunks with adaptive.report.read to create a real phone attachment if phone file tools support it; a local path is not a delivered attachment.'),
 'adaptive.reports':spec('List the board daily PDF reports.'),
 'adaptive.report.read':spec('Read a bounded 32 KiB base64 chunk of a generated PDF for the paired phone file tools. Reassemble chunks by byte offset; attach the actual resulting PDF before claiming delivery.',required={'file':field('string','Report basename from adaptive.report or adaptive.reports.')},optional={'offset':field('integer','Byte offset, default 0; continue using next_offset until eof.')})
}
